 4: env.put(Context.PROVIDER_URL, sServiceProvider);
 5: // 익명으로 LDAP 인증을 사용
 6: env.put(Context.SECURITY_AUTHENTICATION, “none”);
 7: env.put(Context.SECURITY_PRINCIPAL, sUid);
 8: env.put(Context.SECURITY_CREDENTIALS, sPwd);
